<script setup lang="ts">import {ref,computed} from 'vue';import {useRoute,useRouter} from 'vue-router';import {CarFront,Wrench,MapPin,CalendarDays,MessageSquare,CheckCircle2,ChevronLeft,ChevronRight} from 'lucide-vue-next';import PageHeader from '../components/PageHeader.vue';import {vehicles} from '../data/mock';import {workshops} from '../data/customer';import {useVintro} from '../composables/useVintro';const route=useRoute();const router=useRouter();const {addBooking}=useVintro();const workshop=computed(()=>workshops.find(w=>w.id===route.params.workshopId)??workshops[0]);const step=ref(1);const saving=ref(false);const done=ref(false);const form=ref({vehicle:'bmw-320d',service:'Oil service',slot:'',note:'',shareHistory:true});const next=()=>step.value=Math.min(4,step.value+1);const back=()=>step.value=Math.max(1,step.value-1);const confirm=()=>{saving.value=true;setTimeout(()=>{addBooking({id:crypto.randomUUID(),workshop:workshop.value.name,vehicle:vehicles.find(v=>v.id===form.value.vehicle)?.model??'',service:form.value.service,slot:form.value.slot,note:form.value.note,status:'Requested'});saving.value=false;done.value=true},700)}
</script>
<template><PageHeader title="Book service" :back="`/workshops/${workshop.id}`"/><div class="container-app max-w-3xl py-7"><div v-if="!done"><div class="flex items-center gap-2"><span v-for="n in 4" class="h-1.5 flex-1 rounded-full" :class="n<=step?'bg-accent':'bg-stone-200'"/></div><p class="mt-3 text-xs font-medium text-muted">Step {{step}} of 4</p><section class="card mt-6 p-5 md:p-7"><div v-if="step===1"><CarFront :size="23"/><h1 class="mt-5 text-2xl font-semibold">Select vehicle</h1><div class="mt-5 grid gap-3"><label v-for="v in vehicles" class="flex cursor-pointer items-center gap-4 rounded-xl border p-4" :class="{'border-accent bg-emerald-50':form.vehicle===v.id}"><input v-model="form.vehicle" type="radio" :value="v.id" class="accent-[#2d5b4f]"/><img :src="v.image" class="h-14 w-20 rounded-lg object-cover"/><span><strong class="block">{{v.make}} {{v.model}}</strong><small class="nums text-muted">{{v.mileage.toLocaleString()}} km · {{v.vin.slice(-4)}}</small></span></label></div></div><div v-else-if="step===2"><Wrench :size="23"/><h1 class="mt-5 text-2xl font-semibold">What does the vehicle need?</h1><div class="mt-5 grid grid-cols-2 gap-3"><label v-for="s in ['Oil service','Regular service','Brakes','Tyres','Inspection','Repair','Workshop diagnosis','Other']" class="cursor-pointer rounded-xl border p-4 text-sm font-medium" :class="{'border-accent bg-emerald-50':form.service===s}"><input v-model="form.service" type="radio" :value="s" class="sr-only"/>{{s}}</label></div></div><div v-else-if="step===3"><CalendarDays :size="23"/><h1 class="mt-5 text-2xl font-semibold">Choose a time</h1><p class="mt-2 flex items-center gap-1.5 text-sm text-muted"><MapPin :size="15"/>{{workshop.name}}, {{workshop.location}}</p><div class="mt-5 grid gap-3"><label v-for="slot in workshop.slots" class="cursor-pointer rounded-xl border p-4 text-sm font-medium" :class="{'border-accent bg-emerald-50':form.slot===slot}"><input v-model="form.slot" type="radio" :value="slot" class="mr-3 accent-[#2d5b4f]"/>{{slot}}</label></div></div><div v-else><MessageSquare :size="23"/><h1 class="mt-5 text-2xl font-semibold">Review booking</h1><dl class="mt-5 divide-y rounded-xl border px-4"><div class="flex justify-between py-3 text-sm"><dt class="text-muted">Vehicle</dt><dd class="font-semibold">{{vehicles.find(v=>v.id===form.vehicle)?.model}}</dd></div><div class="flex justify-between py-3 text-sm"><dt class="text-muted">Service</dt><dd class="font-semibold">{{form.service}}</dd></div><div class="flex justify-between py-3 text-sm"><dt class="text-muted">Workshop</dt><dd class="font-semibold">{{workshop.name}}</dd></div><div class="flex justify-between py-3 text-sm"><dt class="text-muted">Time</dt><dd class="font-semibold">{{form.slot}}</dd></div></dl><label class="mt-5 block"><span class="label">Note for workshop</span><textarea v-model="form.note" class="field min-h-24" placeholder="Symptoms, requests, or anything useful…"/></label><label class="mt-4 flex gap-3 rounded-xl bg-stone-50 p-4 text-sm"><input v-model="form.shareHistory" type="checkbox" class="accent-[#2d5b4f]"/>Share VIN, mileage and relevant service history with the workshop.</label></div></section><div class="mt-5 flex gap-3"><button v-if="step>1" @click="back" class="btn-secondary flex-1"><ChevronLeft :size="17"/>Back</button><button v-if="step<4" @click="next" class="btn-primary flex-1" :disabled="step===3&&!form.slot">Continue<ChevronRight :size="17"/></button><button v-else @click="confirm" class="btn-primary flex-1" :disabled="saving"><span v-if="saving" class="h-4 w-4 animate-spin rounded-full border-2 border-white/40 border-t-white"/>{{saving?'Sending request…':'Confirm booking'}}</button></div></div><div v-else class="card p-8 text-center"><CheckCircle2 :size="48" class="mx-auto text-success"/><h1 class="mt-5 text-2xl font-semibold">Booking requested</h1><p class="mt-2 text-muted">{{workshop.name}} will confirm {{form.slot}}. We’ll notify you when they respond.</p><RouterLink to="/activity" class="btn-primary mt-7">View activity</RouterLink><button @click="router.push('/')" class="mt-3 block w-full text-sm text-muted">Return to Garage</button></div></div></template>
